-- Central de mídia gerenciável pelo administrador: videoaulas (por matéria/assunto) e podcasts (áudio hospedado).
-- Os alunos leem só o que está ativo; o administrador gerencia tudo em Admin → Central de mídia.
-- Idempotente: pode ser rodado de novo sem duplicar nada.

create table if not exists public.media_videos (
  id uuid primary key default gen_random_uuid(),
  subject text not null,                          -- matéria (ex.: 'Direito Penal')
  topic text not null default '*',                -- assunto; '*' = geral da matéria
  youtube_id text not null,                       -- id do vídeo ou da playlist (PL...)
  title text not null,
  channel text,                                   -- canal de origem (oEmbed do YouTube)
  is_playlist boolean generated always as (youtube_id like 'PL%' and length(youtube_id) > 12) stored,
  embeddable boolean not null default true,       -- false: o autor não permite tocar fora do YouTube
  status text not null default 'unchecked' check (status in ('ok', 'blocked', 'gone', 'unchecked')),
  checked_at timestamptz,
  active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  unique (subject, topic, youtube_id)
);
create index if not exists media_videos_subject_idx on public.media_videos (subject, topic, sort_order);

create table if not exists public.media_podcasts (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  subject text not null,
  description text,
  audio_url text not null,                        -- URL pública do áudio
  audio_path text,                                -- caminho no bucket 'podcasts' (quando enviado pelo painel)
  duration_seconds integer,
  active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);

alter table public.media_videos enable row level security;
alter table public.media_podcasts enable row level security;

drop policy if exists "Read active media videos" on public.media_videos;
create policy "Read active media videos" on public.media_videos
  for select to authenticated using (active or public.has_role(auth.uid(), 'admin'));
drop policy if exists "Admins manage media videos" on public.media_videos;
create policy "Admins manage media videos" on public.media_videos
  for all to authenticated using (public.has_role(auth.uid(), 'admin')) with check (public.has_role(auth.uid(), 'admin'));

drop policy if exists "Read active media podcasts" on public.media_podcasts;
create policy "Read active media podcasts" on public.media_podcasts
  for select to authenticated using (active or public.has_role(auth.uid(), 'admin'));
drop policy if exists "Admins manage media podcasts" on public.media_podcasts;
create policy "Admins manage media podcasts" on public.media_podcasts
  for all to authenticated using (public.has_role(auth.uid(), 'admin')) with check (public.has_role(auth.uid(), 'admin'));

-- Armazenamento dos áudios (leitura pública; só administrador grava).
values ('podcasts', 'podcasts', true, 104857600, array['audio/mpeg', 'audio/mp4', 'audio/x-m4a', 'audio/aac', 'audio/wav', 'audio/ogg', 'audio/webm'])
on conflict (id) do update set public = true, file_size_limit = 104857600,
  allowed_mime_types = array['audio/mpeg', 'audio/mp4', 'audio/x-m4a', 'audio/aac', 'audio/wav', 'audio/ogg', 'audio/webm'];

drop policy if exists "Admins upload podcasts" on storage.objects;
create policy "Admins upload podcasts" on storage.objects for insert to authenticated
  with check (bucket_id = 'podcasts' and public.has_role(auth.uid(), 'admin'));
drop policy if exists "Admins update podcasts" on storage.objects;
create policy "Admins update podcasts" on storage.objects for update to authenticated
  using (bucket_id = 'podcasts' and public.has_role(auth.uid(), 'admin'));
drop policy if exists "Admins delete podcasts" on storage.objects;
create policy "Admins delete podcasts" on storage.objects for delete to authenticated
  using (bucket_id = 'podcasts' and public.has_role(auth.uid(), 'admin'));

-- Catálogo inicial: videoaulas gratuitas pesquisadas e conferidas no YouTube em 04/10/2026
-- (oEmbed: 200 = disponível; 401/403 = o autor não permite exibir fora do YouTube; 404 = removido, não incluído).
on conflict (subject, topic, youtube_id) do nothing;
